import { expect, expectStatus, test, uniqueName } from "../../fixtures";

// Assumes USERS includes a Globex Procurement member persona (key "globex_member").
// Adjust the persona key to match the seeded user list in fixtures/users.ts.
test.describe("manage vendors: tenant isolation", () => {
  test("Vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ apiAs }) => {
    // Arrange: a vendor that exists in the Globex Procurement tenant
    const globex = await apiAs("globex_member");
    const created = await globex.post("/api/vendors", {
      data: {
        name: uniqueName("Globex Vendor"),
        category: "services",
        contact_email: "ops@globex.test",
      },
    });
    const globexVendor = await expectStatus<{ id: string }>(created, 201);

    // Act: the signed-in Northwind member requests that vendor by id
    const member = await apiAs("member");
    const response = await member.get(`/api/vendors/${globexVendor.id}`);

    // Assert
    const body = await expectStatus<{ error: { code: string } }>(response, 404);
    expect(body.error.code).toBe("vendor_not_found");
  });
});
